package com.truckload.controller;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.util.LruCache;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
/** Native OSM raster map. Fetches only visible tiles; honours caching and conditional requests. */
public final class GpsMapView extends View {
 private final Paint paint=new Paint(3);private final LruCache<String,Bitmap> memory=new LruCache<>(48);private final Set<String> queued=Collections.synchronizedSet(new HashSet<>());private final Map<String,Long> retry=new ConcurrentHashMap<>();private final ExecutorService worker=Executors.newFixedThreadPool(2);private final File disk;private volatile boolean attached=false,closed=false;
 private double lat=Double.NaN,lon=Double.NaN,plantLat,plantLon,cx,cy;private int radius,zoom=15;private boolean fixed=false,plant=false,centered=false,follow=true;private float downX,downY;private String error="";private final float dp;
 public GpsMapView(Context context){super(context);dp=getResources().getDisplayMetrics().density;disk=new File(context.getCacheDir(),"osm-tiles");disk.mkdirs();setContentDescription("Heltec GPS map, waiting for a satellite fix");setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
 public void position(Telemetry m,boolean connected){fixed=connected&&m.gpsFix;lat=m.latitude;lon=m.longitude;plant=connected&&m.plant&&Double.isFinite(m.plantLat)&&Double.isFinite(m.plantLon)&&Math.abs(m.plantLat)<=90&&Math.abs(m.plantLon)<=180;plantLat=m.plantLat;plantLon=m.plantLon;radius=m.radius;if(fixed&&(!centered||follow)){cx=MapProjection.x(lon,zoom);cy=MapProjection.y(lat,zoom);centered=true;}else if(!centered&&plant){cx=MapProjection.x(plantLon,zoom);cy=MapProjection.y(plantLat,zoom);centered=true;}setContentDescription(fixed?String.format(Locale.US,"Heltec GPS map at %.6f, %.6f",lat,lon):"GPS map, no live satellite fix");invalidate();}
 public void zoom(int change){int next=Math.max(3,Math.min(19,zoom+change));double factor=Math.pow(2,next-zoom);cx*=factor;cy*=factor;zoom=next;invalidate();}
 public void follow(){follow=true;if(fixed){cx=MapProjection.x(lon,zoom);cy=MapProjection.y(lat,zoom);centered=true;}invalidate();}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;invalidate();}
 @Override protected void onDetachedFromWindow(){attached=false;super.onDetachedFromWindow();}
 public void close(){closed=true;attached=false;worker.shutdownNow();}
 private float sx(double longitude){return (float)(getWidth()/2+MapProjection.near(MapProjection.x(longitude,zoom)-cx,zoom));}
 private float sy(double latitude){return (float)(getHeight()/2+MapProjection.y(latitude,zoom)-cy);}
 @Override protected void onDraw(Canvas canvas){canvas.drawColor(0xff102031);int drawn=0;if(centered){int minX=(int)Math.floor((cx-getWidth()/2)/256),maxX=(int)Math.floor((cx+getWidth()/2)/256),minY=Math.max(0,(int)Math.floor((cy-getHeight()/2)/256)),maxY=Math.min((1<<zoom)-1,(int)Math.floor((cy+getHeight()/2)/256));for(int x=minX;x<=maxX;x++)for(int y=minY;y<=maxY;y++){int wrapped=((x%(1<<zoom))+(1<<zoom))%(1<<zoom);String key=zoom+"_"+wrapped+"_"+y;Bitmap bitmap=memory.get(key);float left=(float)(x*256-cx+getWidth()/2),top=(float)(y*256-cy+getHeight()/2);if(bitmap!=null){canvas.drawBitmap(bitmap,null,new RectF(left,top,left+256,top+256),paint);drawn++;}else{paint.setColor(0xff20384b);paint.setStyle(Paint.Style.STROKE);canvas.drawRect(left,top,left+256,top+256,paint);paint.setStyle(Paint.Style.FILL);request(key,zoom,wrapped,y);}}
 if(plant){float x=sx(plantLon),y=sy(plantLat);float r=(float)(radius*MapProjection.world(zoom)/(40075016.686*Math.cos(Math.toRadians(Math.max(-85,Math.min(85,plantLat))))));paint.setColor(0x4054d6b4);canvas.drawCircle(x,y,r,paint);paint.setColor(0xff268a70);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2*dp);canvas.drawCircle(x,y,r,paint);paint.setStyle(Paint.Style.FILL);canvas.drawCircle(x,y,5*dp,paint);}
 if(fixed){float x=sx(lon),y=sy(lat);paint.setColor(0xff142338);canvas.drawCircle(x,y,11*dp,paint);paint.setColor(0xff38a7ff);canvas.drawCircle(x,y,8*dp,paint);paint.setColor(Color.WHITE);canvas.drawCircle(x,y,3*dp,paint);}}
 if(!centered||drawn==0){paint.setTextSize(12*dp);paint.setColor(0xffd8e6ef);String label=!centered?"Waiting for Heltec GPS location":error.isEmpty()?"Loading map…":"Map unavailable · coordinates still work";canvas.drawText(label,12*dp,25*dp,paint);}paint.setColor(0xe6142338);canvas.drawRect(0,getHeight()-23*dp,getWidth(),getHeight(),paint);paint.setColor(0xffd9e8f3);paint.setTextSize(10*dp);canvas.drawText("© OpenStreetMap contributors",8*dp,getHeight()-8*dp,paint);}
 private void request(String key,int z,int x,int y){if(!attached||closed||retry.getOrDefault(key,0L)>System.currentTimeMillis()||!queued.add(key))return;worker.submit(()->{try{if(!attached||closed)return;File png=new File(disk,key+".png"),meta=new File(disk,key+".properties");Properties p=new Properties();if(meta.isFile())try(InputStream in=new FileInputStream(meta)){p.load(in);}long expiry=Long.parseLong(p.getProperty("expires","0"));Bitmap bitmap=png.isFile()?BitmapFactory.decodeFile(png.getPath()):null;if(bitmap!=null){memory.put(key,bitmap);postInvalidate();}if(bitmap==null||expiry<System.currentTimeMillis()){if(!attached||closed)return;HttpURLConnection c=(HttpURLConnection)new URL("https://tile.openstreetmap.org/"+z+"/"+x+"/"+y+".png").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent","TruckloadAndroid/0.3.0 (+https://github.com/heindpl1/Truck-Load-android-app)");if(p.containsKey("etag"))c.setRequestProperty("If-None-Match",p.getProperty("etag"));if(p.containsKey("modified"))c.setIfModifiedSince(Long.parseLong(p.getProperty("modified")));try{int status=c.getResponseCode();if(status==200){byte[] bytes;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>1048576)throw new IOException();out.write(buffer,0,n);}bytes=out.toByteArray();}bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null)throw new IOException();try(FileOutputStream out=new FileOutputStream(png)){out.write(bytes);}memory.put(key,bitmap);}else if(status!=304||bitmap==null)throw new IOException("Tile unavailable");long life=7L*24*3600*1000;String control=c.getHeaderField("Cache-Control");if(control!=null){java.util.regex.Matcher m=java.util.regex.Pattern.compile("max-age=(\\d+)").matcher(control);if(m.find())life=Long.parseLong(m.group(1))*1000;}long expires=c.getHeaderFieldDate("Expires",0);p.setProperty("expires",Long.toString(expires>0?expires:System.currentTimeMillis()+life));String etag=c.getHeaderField("ETag");if(etag!=null)p.setProperty("etag",etag);long modified=c.getLastModified();if(modified>0)p.setProperty("modified",Long.toString(modified));try(OutputStream out=new FileOutputStream(meta)){p.store(out,null);}error="";}finally{c.disconnect();}}postInvalidate();}catch(Exception e){retry.put(key,System.currentTimeMillis()+60000);error="unavailable";postInvalidate();}finally{queued.remove(key);}});}
 @Override public boolean onTouchEvent(MotionEvent event){if(event.getAction()==MotionEvent.ACTION_DOWN){downX=event.getX();downY=event.getY();getParent().requestDisallowInterceptTouchEvent(true);return true;}if(event.getAction()==MotionEvent.ACTION_MOVE&&centered){follow=false;cx-=event.getX()-downX;cy=Math.max(0,Math.min(MapProjection.world(zoom),cy-(event.getY()-downY)));cx=(cx%MapProjection.world(zoom)+MapProjection.world(zoom))%MapProjection.world(zoom);downX=event.getX();downY=event.getY();invalidate();return true;}if(event.getAction()==MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(false);if(event.getY()>getHeight()-24*dp){getContext().startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.openstreetmap.org/copyright")));}performClick();return true;}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
